    "By accessing and using UNO Bank's services, you agree to be bound by these Terms and Conditions. If you do not agree with any part of these terms, you must not use our services. These terms constitute a legally binding agreement between you and UNO Bank. We reserve the right to modify these terms at any time without prior notice. Continued use of our services after any changes constitutes acceptance of the modified terms.": "यूएनओ बैंक की सेवाओं तक पहुंच और उपयोग करके, आप इन नियमों और शर्तों से बंधे होने के लिए सहमत हैं। यदि आप इन शर्तों के किसी भी भाग से सहमत नहीं हैं, तो आपको हमारी सेवाओं का उपयोग नहीं करना चाहिए। ये शर्तें आपके और यूएनओ बैंक के बीच कानूनी रूप से बाध्यकारी समझौता बनाती हैं। हम बिना किसी पूर्व सूचना के किसी भी समय इन शर्तों को संशोधित करने का अधिकार सुरक्षित रखते हैं। किसी भी बदलाव के बाद हमारी सेवाओं का निरंतर उपयोग संशोधित शर्तों की स्वीकृति माना जाता है।",
