    "Fixed Deposit": "सावधि जमा",
    "Fixed Deposit Details": "सावधि जमा विवरण",
    "Fixed Deposit Terms and Conditions": "सावधि जमा नियम और शर्तें",
    "Fixed Deposits are subject to minimum and maximum deposit limits as specified on our platform. Interest rates are determined based on tenure, amount, and prevailing market conditions. Premature withdrawal may attract penalty charges as per RBI guidelines. Interest is credited as per the frequency selected at the time of FD opening. TDS will be deducted as per Income Tax regulations if interest exceeds the threshold limit.": "सावधि जमा हमारे प्लेटफ़ॉर्म पर निर्दिष्ट न्यूनतम और अधिकतम जमा सीमा के अधीन हैं। ब्याज दरें कार्यकाल, राशि और मौजूदा बाजार स्थितियों के आधार पर निर्धारित की जाती हैं। आरबीआई दिशानिर्देशों के अनुसार समय से पहले निकासी पर जुर्माना लगाया जा सकता है। एफडी खोलने के समय चुनी गई आवृत्ति के अनुसार ब्याज जमा किया जाता है। यदि ब्याज सीमा से अधिक है तो आयकर नियमों के अनुसार टीडीएस काटा जाएगा।",
    "Flexible Tenures": "लचीले कार्यकाल",
    "Form 15G/15H can be submitted to avoid TDS if eligible.": "पात्र होने पर टीडीएस से बचने के लिए फॉर्म 15जी/15एच जमा किया जा सकता है।",
    "Former tech lead at Fortune 500 companies": "फॉर्च्यून 500 कंपनियों में पूर्व तकनीकी प्रमुख",
    "Founded with a vision to revolutionize the banking experience in India, UNO Bank has grown from a small startup to a trusted financial institution serving over a million customers. Our journey began with a simple belief: that banking should be simple, transparent, and accessible to everyone.": "भारत में बैंकिंग अनुभव में क्रांतिकारी बदलाव लाने की दृष्टि से स्थापित, यूएनओ बैंक एक छोटे स्टार्टअप से एक मिलियन से अधिक ग्राहकों को सेवा प्रदान करने वाला एक विश्वसनीय वित्तीय संस्थान बन गया है। हमारी यात्रा एक साधारण विश्वास के साथ शुरू हुई: बैंकिंग सरल, पारदर्शी और सभी के लिए सुलभ होनी चाहिए।",
    "Frequently Asked Questions": "अक्सर पूछे जाने वाले प्रश्नों",
