    "Got questions? We've got answers": "प्रश्न मिले? हमें उत्तर मिल गए हैं",
    "Grievance redressal mechanism is available within 30 working days.": "शिकायत निवारण तंत्र 30 कार्य दिवसों के भीतर उपलब्ध है।",
