    "On Maturity": "परिपक्वता पर",
    "On maturity, the principal amount along with the accrued interest will be credited to your registered bank account. You will receive a notification before the maturity date.": "परिपक्वता पर, मूल राशि और अर्जित ब्याज आपके पंजीकृत बैंक खाते में जमा कर दिए जाएंगे। आपको परिपक्वता तिथि से पहले एक अधिसूचना प्राप्त होगी।",
    "On maturity, the principal and accrued interest will be credited to the linked bank account.": "परिपक्वता पर, मूलधन और अर्जित ब्याज लिंक किए गए बैंक खाते में जमा किया जाएगा।",
    "Open FD accounts and process transactions in real-time with zero delays.": "एफडी खाते खोलें और शून्य विलंब के साथ वास्तविक समय में लेनदेन की प्रक्रिया करें।",
    "Order": "आदेश",
    "Other": "अन्य",
    "Our Mission": "हमारा विशेष कार्य",
    "Our Story": "हमारी कहानी",
    "Our Vision": "हमारा नज़रिया",
    "Our customers are at the heart of everything we do. We prioritize your financial well-being by offering transparent products, no hidden fees, and personalized support. Our dedicated relationship managers are available 24/7 to assist you with your investment decisions, ensuring you always make informed choices that align with your financial goals.": "हम जो कुछ भी करते हैं उसके केंद्र में हमारे ग्राहक होते हैं। हम पारदर्शी उत्पाद, कोई छिपी हुई फीस नहीं और वैयक्तिकृत सहायता प्रदान करके आपकी वित्तीय भलाई को प्राथमिकता देते हैं। हमारे समर्पित रिलेशनशिप मैनेजर आपके निवेश निर्णयों में आपकी सहायता के लिए 24/7 उपलब्ध हैं, यह सुनिश्चित करते हुए कि आप हमेशा सूचित विकल्प चुनें जो आपके वित्तीय लक्ष्यों के अनुरूप हों।",
    "Our platform may contain links to third-party websites or services. We are not responsible for the privacy practices or content of external sites. We encourage you to review the privacy policies of any third-party sites you visit. Our privacy policy applies only to information collected on our platform. Third-party links are provided for convenience and do not imply endorsement.": "हमारे प्लेटफ़ॉर्म में तृतीय-पक्ष वेबसाइटों या सेवाओं के लिंक हो सकते हैं। हम बाहरी साइटों की गोपनीयता प्रथाओं या सामग्री के लिए ज़िम्मेदार नहीं हैं। हम आपको आपके द्वारा देखी जाने वाली किसी भी तृतीय-पक्ष साइट की गोपनीयता नीतियों की समीक्षा करने के लिए प्रोत्साहित करते हैं। हमारी गोपनीयता नीति केवल हमारे प्लेटफ़ॉर्म पर एकत्र की गई जानकारी पर लागू होती है। तृतीय-पक्ष लिंक सुविधा के लिए प्रदान किए जाते हैं और इसका तात्पर्य समर्थन नहीं है।",
    "Our services are not intended for individuals under the age of 18. We do not knowingly collect personal information from children. If we discover that we have collected information from a minor, we will take immediate steps to delete such information. Parents or guardians may contact us regarding data collection involving minors.": "हमारी सेवाएँ 18 वर्ष से कम आयु के व्यक्तियों के लिए नहीं हैं। हम जानबूझकर बच्चों से व्यक्तिगत जानकारी एकत्र नहीं करते हैं। यदि हमें पता चलता है कि हमने किसी नाबालिग से जानकारी एकत्र की है, तो हम ऐसी जानकारी को हटाने के लिए तत्काल कदम उठाएंगे। नाबालिगों से जुड़े डेटा संग्रह के संबंध में माता-पिता या अभिभावक हमसे संपर्क कर सकते हैं।",
    "Over the years, we have stayed true to our core values while embracing innovation. Today, we are proud to be at the forefront of digital banking, offering cutting-edge solutions without compromising on the personal touch that sets us apart.": "इन वर्षों में, हम नवाचार को अपनाते हुए अपने मूल मूल्यों के प्रति सच्चे रहे हैं। आज, हमें डिजिटल बैंकिंग में सबसे आगे होने पर गर्व है, जो हमें अलग करने वाले व्यक्तिगत स्पर्श से समझौता किए बिना अत्याधुनिक समाधान पेश करता है।",
