    "TDS (Tax Deducted at Source) will be deducted if interest exceeds ₹40,000 per year (₹50,000 for senior citizens).": "यदि ब्याज प्रति वर्ष ₹40,000 (वरिष्ठ नागरिकों के लिए ₹50,000) से अधिक है तो टीडीएस (स्रोत पर कर कटौती) काटा जाएगा।",
    "Tax Saver FD has a 5-year lock-in period": "टैक्स सेवर एफडी में 5 साल की लॉक-इन अवधि होती है",
    "Tax Saver FD has a minimum tenure of 5 years with lock-in period.": "टैक्स सेवर एफडी की लॉक-इन अवधि के साथ न्यूनतम अवधि 5 वर्ष है।",
    "Tax Saver FD offers tax deduction under Section 80C up to ₹1.5 lakh.": "टैक्स सेवर एफडी धारा 80सी के तहत ₹1.5 लाख तक कर कटौती प्रदान करता है।",
    "Tax Saver FDs cannot be withdrawn before the 5-year lock-in period.": "टैक्स सेवर एफडी को 5 साल की लॉक-इन अवधि से पहले नहीं निकाला जा सकता है।",
