    "Terms and Conditions": "नियम और शर्तें",
    "Thank you for contacting us! We'll get back to you within 24 hours.": "हमसे संपर्क करने के लिए धन्यवाद! हम 24 घंटे के भीतर आपसे संपर्क करेंगे।",
    "The bank reserves the right to modify these terms with prior notice.": "बैंक पूर्व सूचना के साथ इन शर्तों को संशोधित करने का अधिकार सुरक्षित रखता है।",
    "The minimum deposit amount for a Fixed Deposit is ₹1,000. However, for better returns, we recommend a minimum deposit of ₹10,000.": "फिक्स्ड डिपॉजिट के लिए न्यूनतम जमा राशि ₹1,000 है। हालाँकि, बेहतर रिटर्न के लिए, हम न्यूनतम ₹10,000 जमा करने की सलाह देते हैं।",
    "The minimum deposit amount for opening a Fixed Deposit account with UNO Bank is ₹10,000. This applies across all our FD products.": "यूएनओ बैंक में फिक्स्ड डिपॉजिट खाता खोलने के लिए न्यूनतम जमा राशि ₹10,000 है। यह हमारे सभी FD उत्पादों पर लागू होता है।",
    "These terms are governed by the laws of the Republic of India. The Banking Regulation Act, RBI guidelines, and other applicable laws apply. Any legal action must be initiated in the courts of Mumbai, India. We comply with all regulatory requirements issued by the Reserve Bank of India. These terms supersede all prior agreements between you and UNO Bank.": "ये शर्तें भारत गणराज्य के कानूनों द्वारा शासित होती हैं। बैंकिंग विनियमन अधिनियम, आरबीआई दिशानिर्देश और अन्य लागू कानून लागू होते हैं। कोई भी कानूनी कार्रवाई मुंबई, भारत की अदालतों में शुरू की जानी चाहिए। हम भारतीय रिज़र्व बैंक द्वारा जारी सभी नियामक आवश्यकताओं का अनुपालन करते हैं। ये शर्तें आपके और यूएनओ बैंक के बीच सभी पूर्व समझौतों का स्थान लेती हैं।",
    "This package contains {0} fixed deposits with pre-configured amounts and tenures.": "इस पैकेज में पूर्व-कॉन्फ़िगर राशि और अवधि के साथ {0} सावधि जमा शामिल हैं।",
    "Time advance error:": "समय अग्रिम त्रुटि:",
    "Time advanced by 1 month successfully!": "समय सफलतापूर्वक 1 माह आगे बढ़ गया!",
    "Time advanced:": "समय आगे बढ़ा:",
    "Time reset error:": "समय रीसेट त्रुटि:",
    "Time reset successfully!": "समय सफलतापूर्वक रीसेट हो गया!",
    "Time reset:": "समय रीसेट:",
    "To become India's most trusted and customer-centric bank, known for our innovative products, ethical practices, and unwavering commitment to customer success. We envision a future where quality banking is accessible to every Indian, regardless of their location or financial background.": "भारत का सबसे भरोसेमंद और ग्राहक-केंद्रित बैंक बनना, जो हमारे नवोन्वेषी उत्पादों, नैतिक प्रथाओं और ग्राहकों की सफलता के प्रति अटूट प्रतिबद्धता के लिए जाना जाता है। हम एक ऐसे भविष्य की कल्पना करते हैं जहां गुणवत्तापूर्ण बैंकिंग हर भारतीय के लिए सुलभ हो, चाहे उनका स्थान या वित्तीय पृष्ठभूमि कुछ भी हो।",
    "To democratize wealth creation by providing secure, transparent, and accessible banking solutions that empower every Indian to achieve their financial dreams. We are committed to building long-term relationships with our customers based on trust, integrity, and mutual growth.": "सुरक्षित, पारदर्शी और सुलभ बैंकिंग समाधान प्रदान करके धन सृजन को लोकतांत्रिक बनाना जो प्रत्येक भारतीय को अपने वित्तीय सपनों को प्राप्त करने के लिए सशक्त बनाता है। हम विश्वास, अखंडता और पारस्परिक विकास के आधार पर अपने ग्राहकों के साथ दीर्घकालिक संबंध बनाने के लिए प्रतिबद्ध हैं।",
    "To open a Fixed Deposit account, log in to your dashboard, click on \"Apply FD\", fill in the required details including principal amount, tenure, and interest type, and submit your application. Your FD will be created instantly.": "फिक्स्ड डिपॉजिट खाता खोलने के लिए, अपने डैशबोर्ड पर लॉग इन करें, \"एफडी लागू करें\" पर क्लिक करें, मूल राशि, कार्यकाल और ब्याज प्रकार सहित आवश्यक विवरण भरें, और अपना आवेदन जमा करें। आपकी एफडी तुरंत बन जाएगी.",
    "To use our services, you must register an account by providing accurate and complete information. You are responsible for maintaining the confidentiality of your account credentials. You agree to notify us immediately of any unauthorized use of your account. You must be at least 18 years old to open an account with UNO Bank. We reserve the right to suspend or terminate accounts that violate these terms.": "हमारी सेवाओं का उपयोग करने के लिए, आपको सटीक और संपूर्ण जानकारी प्रदान करके एक खाता पंजीकृत करना होगा। आप अपने खाते के क्रेडेंशियल्स की गोपनीयता बनाए रखने के लिए जिम्मेदार हैं। आप अपने खाते के किसी भी अनधिकृत उपयोग के बारे में हमें तुरंत सूचित करने के लिए सहमत हैं। यूएनओ बैंक में खाता खोलने के लिए आपकी आयु कम से कम 18 वर्ष होनी चाहिए। हम इन शर्तों का उल्लंघन करने वाले खातों को निलंबित या समाप्त करने का अधिकार सुरक्षित रखते हैं।",
