    "UNO": "UNO",
    "UNO Bank Headquarters": "यूएनओ बैंक मुख्यालय",
    "UNO Bank Headquarters, Banking Sector, Mumbai - 400001": "यूएनओ बैंक मुख्यालय, बैंकिंग क्षेत्र, मुंबई - 400001",
    "UNO Bank Headquarters, Mumbai, Maharashtra, India": "यूएनओ बैंक मुख्यालय, मुंबई, महाराष्ट्र, भारत",
    "UNO Bank Privacy Officer, Mumbai, Maharashtra, India": "यूएनओ बैंक गोपनीयता अधिकारी, मुंबई, महाराष्ट्र, भारत",
    "UNO Bank has transformed how I manage my investments. The competitive rates and seamless interface make it my go-to for fixed deposits.": "यूएनओ बैंक ने मेरे निवेश के प्रबंधन के तरीके को बदल दिया है। प्रतिस्पर्धी दरें और निर्बाध इंटरफ़ेस इसे सावधि जमा के लिए मेरा पसंदीदा बनाते हैं।",
    "UNO Bank operates under the strict regulatory framework of the Reserve Bank of India. We adhere to all banking regulations, maintain statutory liquidity ratios, and undergo regular audits to ensure the highest standards of financial integrity. Your deposits are insured up to ₹5 lakh under the DICGC scheme, providing you with complete peace of mind.": "यूएनओ बैंक भारतीय रिजर्व बैंक के सख्त नियामक ढांचे के तहत काम करता है। हम सभी बैंकिंग नियमों का पालन करते हैं, वैधानिक तरलता अनुपात बनाए रखते हैं, और वित्तीय अखंडता के उच्चतम मानकों को सुनिश्चित करने के लिए नियमित ऑडिट से गुजरते हैं। डीआईसीजीसी योजना के तहत आपकी जमा राशि पर ₹5 लाख तक का बीमा किया जाता है, जिससे आपको पूर्ण मानसिक शांति मिलती है।",
    "UNO Bank shall not be liable for any indirect, incidental, or consequential damages. Our liability is limited to the amount of your deposit with us. We are not responsible for losses caused by force majeure events. Technical issues may temporarily affect service availability. We strive to maintain 99.9% uptime but cannot guarantee uninterrupted service.": "यूएनओ बैंक किसी भी अप्रत्यक्ष, आकस्मिक या परिणामी क्षति के लिए उत्तरदायी नहीं होगा। हमारा दायित्व हमारे पास आपकी जमा राशि तक सीमित है। अप्रत्याशित घटना से होने वाले नुकसान के लिए हम जिम्मेदार नहीं हैं। तकनीकी समस्याएँ अस्थायी रूप से सेवा उपलब्धता को प्रभावित कर सकती हैं। हम 99.9% अपटाइम बनाए रखने का प्रयास करते हैं लेकिन निर्बाध सेवा की गारंटी नहीं दे सकते।",
