    "Access denied. Your account may be locked or inactive.": "ಪ್ರವೇಶವನ್ನು ನಿರಾಕರಿಸಲಾಗಿದೆ. ನಿಮ್ಮ ಖಾತೆಯು ಲಾಕ್ ಆಗಿರಬಹುದು ಅಥವಾ ನಿಷ್ಕ್ರಿಯವಾಗಿರಬಹುದು.",
    "Access your accounts anytime, anywhere with our secure online platform.": "ನಮ್ಮ ಸುರಕ್ಷಿತ ಆನ್‌ಲೈನ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನೊಂದಿಗೆ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ, ಎಲ್ಲಿಯಾದರೂ ನಿಮ್ಮ ಖಾತೆಗಳನ್ನು ಪ್ರವೇಶಿಸಿ.",
