    "Advance time by 1 month (Test Mode)": "1 ತಿಂಗಳ ಮುಂಗಡ ಸಮಯ (ಪರೀಕ್ಷಾ ಮೋಡ್)",
    "Advance time by 1 month? This will trigger interest accrual and maturity checks.": "1 ತಿಂಗಳ ಮುಂಗಡ ಸಮಯ? ಇದು ಬಡ್ಡಿ ಸಂಚಯ ಮತ್ತು ಮೆಚುರಿಟಿ ಚೆಕ್‌ಗಳನ್ನು ಪ್ರಚೋದಿಸುತ್ತದೆ.",
    "Advanced Reports": "ಸುಧಾರಿತ ವರದಿಗಳು",
    "Age": "ವಯಸ್ಸು",
