    "Age must be between 18 and 120": "ವಯಸ್ಸು 18 ಮತ್ತು 120 ರ ನಡುವೆ ಇರಬೇಕು",
    "All Portfolios": "ಎಲ್ಲಾ ಪೋರ್ಟ್ಫೋಲಿಯೋಗಳು",
    "All Products": "ಎಲ್ಲಾ ಉತ್ಪನ್ನಗಳು",
    "All Status": "ಎಲ್ಲಾ ಸ್ಥಿತಿ",
    "All applications:": "ಎಲ್ಲಾ ಅಪ್ಲಿಕೇಶನ್‌ಗಳು:",
    "All communications will be encrypted and secured.": "ಎಲ್ಲಾ ಸಂವಹನಗಳನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ ಮತ್ತು ಸುರಕ್ಷಿತಗೊಳಿಸಲಾಗುತ್ತದೆ.",
    "All data is encrypted using military-grade AES-256 encryption": "ಮಿಲಿಟರಿ ದರ್ಜೆಯ AES-256 ಗೂಢಲಿಪೀಕರಣವನ್ನು ಬಳಸಿಕೊಂಡು ಎಲ್ಲಾ ಡೇಟಾವನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ",
    "All disputes will be subject to the jurisdiction of Mumbai courts.": "ಎಲ್ಲಾ ವಿವಾದಗಳು ಮುಂಬೈ ನ್ಯಾಯಾಲಯಗಳ ವ್ಯಾಪ್ತಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ.",
    "All payments must be made through authorized banking channels. We accept payments via NEFT, IMPS, UPI, and net banking. Transaction processing times vary based on the payment method selected. We are not responsible for delays caused by third-party payment processors. All transactions are subject to verification and fraud detection protocols.": "ಎಲ್ಲಾ ಪಾವತಿಗಳನ್ನು ಅಧಿಕೃತ ಬ್ಯಾಂಕಿಂಗ್ ಚಾನೆಲ್‌ಗಳ ಮೂಲಕ ಮಾಡಬೇಕು. ನಾವು NEFT, IMPS, UPI ಮತ್ತು ನೆಟ್ ಬ್ಯಾಂಕಿಂಗ್ ಮೂಲಕ ಪಾವತಿಗಳನ್ನು ಸ್ವೀಕರಿಸುತ್ತೇವೆ. ಆಯ್ಕೆಮಾಡಿದ ಪಾವತಿ ವಿಧಾನವನ್ನು ಆಧರಿಸಿ ವಹಿವಾಟಿನ ಪ್ರಕ್ರಿಯೆಯ ಸಮಯಗಳು ಬದಲಾಗುತ್ತವೆ. ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಪಾವತಿ ಪ್ರೊಸೆಸರ್‌ಗಳಿಂದ ಉಂಟಾಗುವ ವಿಳಂಬಗಳಿಗೆ ನಾವು ಜವಾಬ್ದಾರರಾಗಿರುವುದಿಲ್ಲ. ಎಲ್ಲಾ ವಹಿವಾಟುಗಳು ಪರಿಶೀಲನೆ ಮತ್ತು ವಂಚನೆ ಪತ್ತೆ ಪ್ರೋಟೋಕಾಲ್‌ಗಳಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ.",
