    "Approve Bundle": "ಬಂಡಲ್ ಅನ್ನು ಅನುಮೋದಿಸಿ",
    "Approve or reject entire FD packages as a single unit": "ಸಂಪೂರ್ಣ FD ಪ್ಯಾಕೇಜ್‌ಗಳನ್ನು ಒಂದೇ ಘಟಕವಾಗಿ ಅನುಮೋದಿಸಿ ಅಥವಾ ತಿರಸ್ಕರಿಸಿ",
    "Approved": "ಅನುಮೋದಿಸಲಾಗಿದೆ",
    "Approving application:": "ಅರ್ಜಿಯನ್ನು ಅನುಮೋದಿಸುವುದು:",
    "Are you sure you want to ban user {0}?": "{0} ಬಳಕೆದಾರರನ್ನು ನಿಷೇಧಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to deactivate user {0}?": "ಬಳಕೆದಾರರ {0} ಅನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to debar officer {0}?": "ಅಧಿಕಾರಿ {0} ಅವರನ್ನು ಡಿಬಾರ್ ಮಾಡಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to prematurely close FD Account {0}? Note: Premature withdrawal may attract penalties. Error: {1}": "ನೀವು ಅಕಾಲಿಕವಾಗಿ FD ಖಾತೆಯನ್ನು ಮುಚ್ಚಲು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ {0}? ಗಮನಿಸಿ: ಅಕಾಲಿಕ ವಾಪಸಾತಿಗೆ ದಂಡ ವಿಧಿಸಬಹುದು. ದೋಷ: {1}",
    "Are you sure you want to proceed with premature closure?": "ಅಕಾಲಿಕ ಮುಚ್ಚುವಿಕೆಯನ್ನು ಮುಂದುವರಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to reintroduce this product?": "ಈ ಉತ್ಪನ್ನವನ್ನು ಮರುಪರಿಚಯಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to retire this product?": "ಈ ಉತ್ಪನ್ನವನ್ನು ನಿವೃತ್ತಿಗೊಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to unban user {0}?": "{0} ಬಳಕೆದಾರರ ನಿಷೇಧವನ್ನು ತೆಗೆದುಹಾಕಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "Are you sure you want to withdraw application {0}?": "ನೀವು ಅಪ್ಲಿಕೇಶನ್ {0} ಅನ್ನು ಹಿಂಪಡೆಯಲು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?",
    "As a senior citizen, I appreciate the special rates and excellent customer service. UNO Bank truly cares about its customers.": "ಹಿರಿಯ ನಾಗರಿಕನಾಗಿ, ನಾನು ವಿಶೇಷ ದರಗಳು ಮತ್ತು ಅತ್ಯುತ್ತಮ ಗ್ರಾಹಕ ಸೇವೆಯನ್ನು ಪ್ರಶಂಸಿಸುತ್ತೇನೆ. UNO ಬ್ಯಾಂಕ್ ತನ್ನ ಗ್ರಾಹಕರ ಬಗ್ಗೆ ನಿಜವಾಗಿಯೂ ಕಾಳಜಿ ವಹಿಸುತ್ತದೆ.",
    "Ascending": "ಆರೋಹಣ",
    "At UNO Bank, we are committed to protecting your privacy and ensuring the security of your personal information. This Privacy Policy explains how we collect, use, and safeguard your data when you use our banking services.": "UNO ಬ್ಯಾಂಕ್‌ನಲ್ಲಿ, ನಿಮ್ಮ ಗೌಪ್ಯತೆಯನ್ನು ರಕ್ಷಿಸಲು ಮತ್ತು ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯ ಸುರಕ್ಷತೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ನಾವು ಬದ್ಧರಾಗಿದ್ದೇವೆ. ನೀವು ನಮ್ಮ ಬ್ಯಾಂಕಿಂಗ್ ಸೇವೆಗಳನ್ನು ಬಳಸುವಾಗ ನಿಮ್ಮ ಡೇಟಾವನ್ನು ನಾವು ಹೇಗೆ ಸಂಗ್ರಹಿಸುತ್ತೇವೆ, ಬಳಸುತ್ತೇವೆ ಮತ್ತು ರಕ್ಷಿಸುತ್ತೇವೆ ಎಂಬುದನ್ನು ಈ ಗೌಪ್ಯತಾ ನೀತಿ ವಿವರಿಸುತ್ತದೆ.",
    "At UNO Bank, we believe that financial growth and environmental responsibility go hand in hand. We are committed to reducing our carbon footprint through paperless operations, green investments, and sustainable banking practices. Every FD you open contributes to our green initiatives, including tree plantation programs and renewable energy projects.": "UNO ಬ್ಯಾಂಕ್‌ನಲ್ಲಿ, ಹಣಕಾಸಿನ ಬೆಳವಣಿಗೆ ಮತ್ತು ಪರಿಸರ ಜವಾಬ್ದಾರಿಯು ಜೊತೆಜೊತೆಯಲ್ಲಿ ಸಾಗುತ್ತದೆ ಎಂದು ನಾವು ನಂಬುತ್ತೇವೆ. ಕಾಗದರಹಿತ ಕಾರ್ಯಾಚರಣೆಗಳು, ಹಸಿರು ಹೂಡಿಕೆಗಳು ಮತ್ತು ಸುಸ್ಥಿರ ಬ್ಯಾಂಕಿಂಗ್ ಅಭ್ಯಾಸಗಳ ಮೂಲಕ ನಮ್ಮ ಇಂಗಾಲದ ಹೆಜ್ಜೆಗುರುತನ್ನು ಕಡಿಮೆ ಮಾಡಲು ನಾವು ಬದ್ಧರಾಗಿದ್ದೇವೆ. ನೀವು ತೆರೆಯುವ ಪ್ರತಿಯೊಂದು ಎಫ್‌ಡಿಯು ಮರ ನೆಡುವ ಕಾರ್ಯಕ್ರಮಗಳು ಮತ್ತು ನವೀಕರಿಸಬಹುದಾದ ಇಂಧನ ಯೋಜನೆಗಳು ಸೇರಿದಂತೆ ನಮ್ಮ ಹಸಿರು ಉಪಕ್ರಮಗಳಿಗೆ ಕೊಡುಗೆ ನೀಡುತ್ತದೆ.",
    "Auto-calculating with pre-filled values...": "ಮೊದಲೇ ತುಂಬಿದ ಮೌಲ್ಯಗಳೊಂದಿಗೆ ಸ್ವಯಂ ಲೆಕ್ಕಾಚಾರ ಮಾಡಲಾಗುತ್ತಿದೆ...",
