    "Best for printing and official documentation": "ಮುದ್ರಣ ಮತ್ತು ಅಧಿಕೃತ ದಾಖಲಾತಿಗಾಗಿ ಉತ್ತಮವಾಗಿದೆ",
    "Beyond profits, we measure our success by the positive impact we create in society. Through our CSR initiatives, we support education for underprivileged children, healthcare programs in rural areas, and financial literacy campaigns. When you bank with UNO, you become part of a larger movement that is working to build a better, more equitable society.": "ಲಾಭವನ್ನು ಮೀರಿ, ಸಮಾಜದಲ್ಲಿ ನಾವು ಸೃಷ್ಟಿಸುವ ಧನಾತ್ಮಕ ಪ್ರಭಾವದಿಂದ ನಾವು ನಮ್ಮ ಯಶಸ್ಸನ್ನು ಅಳೆಯುತ್ತೇವೆ. ನಮ್ಮ CSR ಉಪಕ್ರಮಗಳ ಮೂಲಕ, ನಾವು ಹಿಂದುಳಿದ ಮಕ್ಕಳಿಗೆ ಶಿಕ್ಷಣ, ಗ್ರಾಮೀಣ ಪ್ರದೇಶಗಳಲ್ಲಿ ಆರೋಗ್ಯ ಕಾರ್ಯಕ್ರಮಗಳು ಮತ್ತು ಆರ್ಥಿಕ ಸಾಕ್ಷರತಾ ಅಭಿಯಾನಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತೇವೆ. ನೀವು UNO ನೊಂದಿಗೆ ಬ್ಯಾಂಕ್ ಮಾಡಿದಾಗ, ಉತ್ತಮವಾದ, ಹೆಚ್ಚು ಸಮಾನವಾದ ಸಮಾಜವನ್ನು ನಿರ್ಮಿಸಲು ಕೆಲಸ ಮಾಡುವ ದೊಡ್ಡ ಚಳುವಳಿಯ ಭಾಗವಾಗುತ್ತೀರಿ.",
    "Billing Summary": "ಬಿಲ್ಲಿಂಗ್ ಸಾರಾಂಶ",
    "Building trust through transparency, innovation, and customer-centric banking": "ಪಾರದರ್ಶಕತೆ, ನಾವೀನ್ಯತೆ ಮತ್ತು ಗ್ರಾಹಕ ಕೇಂದ್ರಿತ ಬ್ಯಾಂಕಿಂಗ್ ಮೂಲಕ ನಂಬಿಕೆಯನ್ನು ನಿರ್ಮಿಸುವುದು",
