    "Business Owner": "ವ್ಯಾಪಾರ ಮಾಲೀಕರು",
    "By accessing and using UNO Bank's services, you agree to be bound by these Terms and Conditions. If you do not agree with any part of these terms, you must not use our services. These terms constitute a legally binding agreement between you and UNO Bank. We reserve the right to modify these terms at any time without prior notice. Continued use of our services after any changes constitutes acceptance of the modified terms.": "UNO ಬ್ಯಾಂಕಿನ ಸೇವೆಗಳನ್ನು ಪ್ರವೇಶಿಸುವ ಮತ್ತು ಬಳಸುವ ಮೂಲಕ, ನೀವು ಈ ನಿಯಮಗಳು ಮತ್ತು ಷರತ್ತುಗಳಿಗೆ ಬದ್ಧರಾಗಿರಲು ಒಪ್ಪುತ್ತೀರಿ. ಈ ನಿಯಮಗಳ ಯಾವುದೇ ಭಾಗವನ್ನು ನೀವು ಒಪ್ಪದಿದ್ದರೆ, ನೀವು ನಮ್ಮ ಸೇವೆಗಳನ್ನು ಬಳಸಬಾರದು. ಈ ನಿಯಮಗಳು ನಿಮ್ಮ ಮತ್ತು UNO ಬ್ಯಾಂಕ್ ನಡುವೆ ಕಾನೂನುಬದ್ಧವಾಗಿ ಬಂಧಿಸುವ ಒಪ್ಪಂದವನ್ನು ರೂಪಿಸುತ್ತವೆ. ಪೂರ್ವ ಸೂಚನೆ ಇಲ್ಲದೆ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಈ ನಿಯಮಗಳನ್ನು ಮಾರ್ಪಡಿಸುವ ಹಕ್ಕನ್ನು ನಾವು ಕಾಯ್ದಿರಿಸಿದ್ದೇವೆ. ಯಾವುದೇ ಬದಲಾವಣೆಗಳ ನಂತರ ನಮ್ಮ ಸೇವೆಗಳ ಮುಂದುವರಿದ ಬಳಕೆಯು ಮಾರ್ಪಡಿಸಿದ ನಿಯಮಗಳನ್ನು ಅಂಗೀಕರಿಸುತ್ತದೆ.",
