    "Disputes will be resolved through mutual discussion and negotiation. If unresolved, disputes may be referred to the Banking Ombudsman. Legal proceedings, if any, will be subject to the jurisdiction of Indian courts. Arbitration may be considered for complex commercial disputes. We are committed to fair and transparent dispute resolution practices.": "ಪರಸ್ಪರ ಚರ್ಚೆ ಮತ್ತು ಮಾತುಕತೆ ಮೂಲಕ ವಿವಾದಗಳನ್ನು ಪರಿಹರಿಸಲಾಗುವುದು. ಬಗೆಹರಿಯದಿದ್ದರೆ, ವಿವಾದಗಳನ್ನು ಬ್ಯಾಂಕಿಂಗ್ ಒಂಬುಡ್ಸ್‌ಮನ್‌ಗೆ ಉಲ್ಲೇಖಿಸಬಹುದು. ಕಾನೂನು ಪ್ರಕ್ರಿಯೆಗಳು, ಯಾವುದಾದರೂ ಇದ್ದರೆ, ಭಾರತೀಯ ನ್ಯಾಯಾಲಯಗಳ ವ್ಯಾಪ್ತಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತದೆ. ಸಂಕೀರ್ಣ ವಾಣಿಜ್ಯ ವಿವಾದಗಳಿಗೆ ಮಧ್ಯಸ್ಥಿಕೆಯನ್ನು ಪರಿಗಣಿಸಬಹುದು. ನಾವು ನ್ಯಾಯಯುತ ಮತ್ತು ಪಾರದರ್ಶಕ ವಿವಾದ ಪರಿಹಾರ ಪದ್ಧತಿಗಳಿಗೆ ಬದ್ಧರಾಗಿದ್ದೇವೆ.",
