    "Features": "ವೈಶಿಷ್ಟ್ಯಗಳು",
    "Female": "ಹೆಣ್ಣು",
    "Filtered active apps:": "ಫಿಲ್ಟರ್ ಮಾಡಲಾದ ಸಕ್ರಿಯ ಅಪ್ಲಿಕೇಶನ್‌ಗಳು:",
    "Final Application Summary": "ಅಂತಿಮ ಅಪ್ಲಿಕೇಶನ್ ಸಾರಾಂಶ",
    "Final Payout Amount: {0}": "ಅಂತಿಮ ಪಾವತಿಯ ಮೊತ್ತ: {0}",
    "Final Payout: {0}": "ಅಂತಿಮ ಪಾವತಿ: {0}",
    "Find answers to frequently asked questions about our services": "ನಮ್ಮ ಸೇವೆಗಳ ಕುರಿತು ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಗಳನ್ನು ಹುಡುಕಿ",
    "First Name": "ಮೊದಲ ಹೆಸರು",
    "First Name *": "ಮೊದಲ ಹೆಸರು *",
    "Fixed Deposit": "ಸ್ಥಿರ ಠೇವಣಿ",
    "Fixed Deposit Details": "ಸ್ಥಿರ ಠೇವಣಿ ವಿವರಗಳು",
    "Fixed Deposit Terms and Conditions": "ಸ್ಥಿರ ಠೇವಣಿ ನಿಯಮಗಳು ಮತ್ತು ಷರತ್ತುಗಳು",
    "Fixed Deposits are subject to minimum and maximum deposit limits as specified on our platform. Interest rates are determined based on tenure, amount, and prevailing market conditions. Premature withdrawal may attract penalty charges as per RBI guidelines. Interest is credited as per the frequency selected at the time of FD opening. TDS will be deducted as per Income Tax regulations if interest exceeds the threshold limit.": "ನಮ್ಮ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನಲ್ಲಿ ನಿರ್ದಿಷ್ಟಪಡಿಸಿದಂತೆ ಸ್ಥಿರ ಠೇವಣಿಗಳು ಕನಿಷ್ಠ ಮತ್ತು ಗರಿಷ್ಠ ಠೇವಣಿ ಮಿತಿಗಳಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ. ಅವಧಿ, ಮೊತ್ತ ಮತ್ತು ಚಾಲ್ತಿಯಲ್ಲಿರುವ ಮಾರುಕಟ್ಟೆ ಪರಿಸ್ಥಿತಿಗಳ ಆಧಾರದ ಮೇಲೆ ಬಡ್ಡಿದರಗಳನ್ನು ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ. ಆರ್‌ಬಿಐ ಮಾರ್ಗಸೂಚಿಗಳ ಪ್ರಕಾರ ಅಕಾಲಿಕ ವಾಪಸಾತಿಗೆ ಪೆನಾಲ್ಟಿ ಶುಲ್ಕ ವಿಧಿಸಬಹುದು. FD ತೆರೆಯುವ ಸಮಯದಲ್ಲಿ ಆಯ್ಕೆಮಾಡಿದ ಆವರ್ತನದ ಪ್ರಕಾರ ಬಡ್ಡಿಯನ್ನು ಕ್ರೆಡಿಟ್ ಮಾಡಲಾಗುತ್ತದೆ. ಬಡ್ಡಿ ಮಿತಿಯನ್ನು ಮೀರಿದರೆ ಆದಾಯ ತೆರಿಗೆ ನಿಯಮಗಳ ಪ್ರಕಾರ TDS ಕಡಿತಗೊಳಿಸಲಾಗುತ್ತದೆ.",
    "Flexible Tenures": "ಹೊಂದಿಕೊಳ್ಳುವ ಅವಧಿಗಳು",
    "Form 15G/15H can be submitted to avoid TDS if eligible.": "ಅರ್ಹತೆ ಇದ್ದರೆ TDS ಅನ್ನು ತಪ್ಪಿಸಲು ಫಾರ್ಮ್ 15G/15H ಅನ್ನು ಸಲ್ಲಿಸಬಹುದು.",
    "Former tech lead at Fortune 500 companies": "ಫಾರ್ಚೂನ್ 500 ಕಂಪನಿಗಳಲ್ಲಿ ಮಾಜಿ ಟೆಕ್ ಲೀಡ್",
