    "Bank Details": "ಬ್ಯಾಂಕ್ ವಿವರಗಳು",
    "Founded with a vision to revolutionize the banking experience in India, UNO Bank has grown from a small startup to a trusted financial institution serving over a million customers. Our journey began with a simple belief: that banking should be simple, transparent, and accessible to everyone.": "ಭಾರತದಲ್ಲಿ ಬ್ಯಾಂಕಿಂಗ್ ಅನುಭವವನ್ನು ಕ್ರಾಂತಿಗೊಳಿಸುವ ದೃಷ್ಟಿಯೊಂದಿಗೆ ಸ್ಥಾಪಿತವಾದ UNO ಬ್ಯಾಂಕ್ ಒಂದು ಸಣ್ಣ ಪ್ರಾರಂಭದಿಂದ ಮಿಲಿಯನ್‌ಗಿಂತಲೂ ಹೆಚ್ಚು ಗ್ರಾಹಕರಿಗೆ ಸೇವೆ ಸಲ್ಲಿಸುವ ವಿಶ್ವಾಸಾರ್ಹ ಹಣಕಾಸು ಸಂಸ್ಥೆಯಾಗಿ ಬೆಳೆದಿದೆ. ನಮ್ಮ ಪ್ರಯಾಣವು ಸರಳ ನಂಬಿಕೆಯೊಂದಿಗೆ ಪ್ರಾರಂಭವಾಯಿತು: ಬ್ಯಾಂಕಿಂಗ್ ಸರಳವಾಗಿರಬೇಕು, ಪಾರದರ್ಶಕವಾಗಿರಬೇಕು ಮತ್ತು ಎಲ್ಲರಿಗೂ ಪ್ರವೇಶಿಸಬಹುದು.",
