    "Got questions? We've got answers": "ಪ್ರಶ್ನೆಗಳಿವೆಯೇ? ನಮಗೆ ಉತ್ತರಗಳಿವೆ",
    "Grievance redressal mechanism is available within 30 working days.": "ಕುಂದುಕೊರತೆ ಪರಿಹಾರ ಕಾರ್ಯವಿಧಾನವು 30 ಕೆಲಸದ ದಿನಗಳಲ್ಲಿ ಲಭ್ಯವಿದೆ.",
