    "How It Works": "ಇದು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
    "How do I check my FD balance?": "ನನ್ನ FD ಬ್ಯಾಲೆನ್ಸ್ ಅನ್ನು ನಾನು ಹೇಗೆ ಪರಿಶೀಲಿಸುವುದು?",
    "How do I open a Fixed Deposit account?": "ನಾನು ಫಿಕ್ಸೆಡ್ ಡೆಪಾಸಿಟ್ ಖಾತೆಯನ್ನು ಹೇಗೆ ತೆರೆಯುವುದು?",
    "How is interest calculated?": "ಬಡ್ಡಿಯನ್ನು ಹೇಗೆ ಲೆಕ್ಕ ಹಾಕಲಾಗುತ್ತದೆ?",
    "How is the interest calculated on my FD?": "ನನ್ನ FD ಮೇಲಿನ ಬಡ್ಡಿಯನ್ನು ಹೇಗೆ ಲೆಕ್ಕ ಹಾಕಲಾಗುತ್ತದೆ?",
    "I have read, understood, and agree to the above Terms & Conditions": "ಮೇಲಿನ ನಿಯಮಗಳು ಮತ್ತು ಷರತ್ತುಗಳನ್ನು ನಾನು ಓದಿದ್ದೇನೆ, ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಒಪ್ಪುತ್ತೇನೆ",
    "I love the transparency and ease of use. The FD calculator helped me plan my investments perfectly. Highly recommended!": "ನಾನು ಪಾರದರ್ಶಕತೆ ಮತ್ತು ಬಳಕೆಯ ಸುಲಭತೆಯನ್ನು ಪ್ರೀತಿಸುತ್ತೇನೆ. ಎಫ್‌ಡಿ ಕ್ಯಾಲ್ಕುಲೇಟರ್ ನನ್ನ ಹೂಡಿಕೆಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಯೋಜಿಸಲು ನನಗೆ ಸಹಾಯ ಮಾಡಿದೆ. ಹೆಚ್ಚು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ!",
    "IFSC Code": "IFSC ಕೋಡ್",
    "IFSC Code *": "IFSC ಕೋಡ್*",
    "INACTIVE": "ನಿಷ್ಕ್ರಿಯ",
    "INR": "INR",
    "Ideal for data analysis and importing into other systems": "ಡೇಟಾ ವಿಶ್ಲೇಷಣೆ ಮತ್ತು ಇತರ ವ್ಯವಸ್ಥೆಗಳಿಗೆ ಆಮದು ಮಾಡಿಕೊಳ್ಳಲು ಸೂಕ್ತವಾಗಿದೆ",
    "If no instructions are given, the FD will be automatically renewed for the same tenure.": "ಯಾವುದೇ ಸೂಚನೆಗಳನ್ನು ನೀಡದಿದ್ದರೆ, ಅದೇ ಅವಧಿಗೆ FD ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನವೀಕರಿಸಲ್ಪಡುತ್ತದೆ.",
    "If you have any questions about these Terms and Conditions, please contact our customer support team:": "ಈ ನಿಯಮಗಳು ಮತ್ತು ಷರತ್ತುಗಳ ಕುರಿತು ನೀವು ಯಾವುದೇ ಪ್ರಶ್ನೆಗಳನ್ನು ಹೊಂದಿದ್ದರೆ, ದಯವಿಟ್ಟು ನಮ್ಮ ಗ್ರಾಹಕ ಬೆಂಬಲ ತಂಡವನ್ನು ಸಂಪರ್ಕಿಸಿ:",
    "If you have any questions, concerns, or requests regarding your privacy, please reach out to us:": "ನಿಮ್ಮ ಗೌಪ್ಯತೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ನೀವು ಯಾವುದೇ ಪ್ರಶ್ನೆಗಳು, ಕಾಳಜಿಗಳು ಅಥವಾ ವಿನಂತಿಗಳನ್ನು ಹೊಂದಿದ್ದರೆ, ದಯವಿಟ್ಟು ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ:",
    "If you have concerns about our data practices, you may contact our Privacy Officer. We will acknowledge your complaint within 48 hours and resolve it within 30 days. For unresolved complaints, you may approach the Banking Ombudsman or relevant authorities. We maintain detailed records of all privacy-related complaints and their resolution. Your privacy concerns are taken seriously and handled with utmost priority.": "ನಮ್ಮ ಡೇಟಾ ಅಭ್ಯಾಸಗಳ ಬಗ್ಗೆ ನಿಮಗೆ ಕಾಳಜಿ ಇದ್ದರೆ, ನೀವು ನಮ್ಮ ಗೌಪ್ಯತೆ ಅಧಿಕಾರಿಯನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು. ನಾವು ನಿಮ್ಮ ದೂರನ್ನು 48 ಗಂಟೆಗಳ ಒಳಗೆ ಅಂಗೀಕರಿಸುತ್ತೇವೆ ಮತ್ತು ಅದನ್ನು 30 ದಿನಗಳಲ್ಲಿ ಪರಿಹರಿಸುತ್ತೇವೆ. ಬಗೆಹರಿಯದ ದೂರುಗಳಿಗಾಗಿ, ನೀವು ಬ್ಯಾಂಕಿಂಗ್ ಒಂಬುಡ್ಸ್‌ಮನ್ ಅಥವಾ ಸಂಬಂಧಿತ ಅಧಿಕಾರಿಗಳನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು. ಎಲ್ಲಾ ಗೌಪ್ಯತೆ-ಸಂಬಂಧಿತ ದೂರುಗಳು ಮತ್ತು ಅವುಗಳ ಪರಿಹಾರದ ವಿವರವಾದ ದಾಖಲೆಗಳನ್ನು ನಾವು ನಿರ್ವಹಿಸುತ್ತೇವೆ. ನಿಮ್ಮ ಗೌಪ್ಯತೆಯ ಕಾಳಜಿಗಳನ್ನು ಗಂಭೀರವಾಗಿ ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತದೆ ಮತ್ತು ಅತ್ಯಂತ ಆದ್ಯತೆಯೊಂದಿಗೆ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ.",
    "In case of the depositor's demise, the amount will be transferred to the nominee.": "ಠೇವಣಿದಾರನ ಮರಣದ ಸಂದರ್ಭದಲ್ಲಿ, ಮೊತ್ತವನ್ನು ನಾಮಿನಿಗೆ ವರ್ಗಾಯಿಸಲಾಗುತ್ತದೆ.",
