    "Includes:": "ಒಳಗೊಂಡಿದೆ:",
    "Indian": "ಭಾರತೀಯ",
    "Innovation-Driven Banking": "ನಾವೀನ್ಯತೆ-ಚಾಲಿತ ಬ್ಯಾಂಕಿಂಗ್",
    "Instant Account Opening": "ತ್ವರಿತ ಖಾತೆ ತೆರೆಯುವಿಕೆ",
    "Instant Processing": "ತ್ವರಿತ ಸಂಸ್ಕರಣೆ",
    "Interest Accrued to Date: {0}": "ದಿನಾಂಕಕ್ಕೆ ಸಂಚಿತವಾದ ಬಡ್ಡಿ: {0}",
    "Interest Accrued: {0}": "ಬಡ್ಡಿ ಸಂಚಿತ: {0}",
    "Interest Earned": "ಬಡ್ಡಿ ಗಳಿಸಿದೆ",
    "Interest Rate": "ಬಡ್ಡಿ ದರ",
    "Interest Rate (%)": "ಬಡ್ಡಿ ದರ (%)",
    "Interest Rate:": "ಬಡ್ಡಿ ದರ:",
    "Interest Report": "ಆಸಕ್ತಿ ವರದಿ",
    "Interest Type": "ಆಸಕ್ತಿಯ ಪ್ರಕಾರ",
    "Interest Type *": "ಆಸಕ್ತಿ ಪ್ರಕಾರ *",
    "Interest Type: {0}": "ಆಸಕ್ತಿಯ ಪ್ರಕಾರ: {0}",
    "Interest can be calculated using either Simple Interest or Compound Interest. Compound Interest is calculated monthly and offers higher returns. You can use our FD Calculator to estimate your returns.": "ಸರಳ ಬಡ್ಡಿ ಅಥವಾ ಸಂಯುಕ್ತ ಬಡ್ಡಿ ಬಳಸಿ ಬಡ್ಡಿಯನ್ನು ಲೆಕ್ಕ ಹಾಕಬಹುದು. ಕಾಂಪೌಂಡ್ ಬಡ್ಡಿಯನ್ನು ಮಾಸಿಕವಾಗಿ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ ಮತ್ತು ಹೆಚ್ಚಿನ ಆದಾಯವನ್ನು ನೀಡುತ್ತದೆ. ನಿಮ್ಮ ಆದಾಯವನ್ನು ಅಂದಾಜು ಮಾಡಲು ನೀವು ನಮ್ಮ FD ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಅನ್ನು ಬಳಸಬಹುದು.",
    "Interest earned on FD is taxable as per the Income Tax Act.": "ಆದಾಯ ತೆರಿಗೆ ಕಾಯಿದೆಯ ಪ್ರಕಾರ FD ಮೇಲೆ ಗಳಿಸಿದ ಬಡ್ಡಿಗೆ ತೆರಿಗೆ ವಿಧಿಸಲಾಗುತ್ತದೆ.",
    "Interest is calculated based on the principal amount, tenure, and applicable interest rate. We offer both simple and compound interest options, with compound interest typically yielding higher returns.": "ಅಸಲು ಮೊತ್ತ, ಅಧಿಕಾರಾವಧಿ ಮತ್ತು ಅನ್ವಯವಾಗುವ ಬಡ್ಡಿ ದರವನ್ನು ಆಧರಿಸಿ ಬಡ್ಡಿಯನ್ನು ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ. ನಾವು ಸರಳ ಮತ್ತು ಸಂಯುಕ್ತ ಬಡ್ಡಿ ಆಯ್ಕೆಗಳನ್ನು ನೀಡುತ್ತೇವೆ, ಸಂಯುಕ್ತ ಬಡ್ಡಿಯು ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚಿನ ಆದಾಯವನ್ನು ನೀಡುತ್ತದೆ.",
    "Interest is calculated quarterly and compounded as per the selected product.": "ಬಡ್ಡಿಯನ್ನು ತ್ರೈಮಾಸಿಕವಾಗಿ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ ಮತ್ತು ಆಯ್ದ ಉತ್ಪನ್ನದ ಪ್ರಕಾರ ಸಂಯೋಜಿತಗೊಳಿಸಲಾಗುತ್ತದೆ.",
    "Interest rates are subject to change and determined by the bank's policy.": "ಬಡ್ಡಿ ದರಗಳು ಬದಲಾವಣೆಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ ಮತ್ತು ಬ್ಯಾಂಕಿನ ನೀತಿಯಿಂದ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ.",
    "Interest rates are subject to change without prior notice based on RBI policy changes. Rates applicable at the time of FD booking will remain fixed for the entire tenure. We reserve the right to offer special promotional rates from time to time. Interest calculation follows the methodology prescribed by the Reserve Bank of India. Maturity amount is guaranteed and will be credited to your registered bank account.": "ಆರ್‌ಬಿಐ ನೀತಿ ಬದಲಾವಣೆಗಳ ಆಧಾರದ ಮೇಲೆ ಬಡ್ಡಿದರಗಳು ಪೂರ್ವ ಸೂಚನೆ ಇಲ್ಲದೆ ಬದಲಾವಣೆಗೆ ಒಳಪಟ್ಟಿರುತ್ತವೆ. FD ಬುಕಿಂಗ್ ಸಮಯದಲ್ಲಿ ಅನ್ವಯವಾಗುವ ದರಗಳು ಸಂಪೂರ್ಣ ಅವಧಿಗೆ ಸ್ಥಿರವಾಗಿರುತ್ತವೆ. ಕಾಲಕಾಲಕ್ಕೆ ವಿಶೇಷ ಪ್ರಚಾರ ದರಗಳನ್ನು ನೀಡುವ ಹಕ್ಕನ್ನು ನಾವು ಕಾಯ್ದಿರಿಸಿದ್ದೇವೆ. ಬಡ್ಡಿ ಲೆಕ್ಕಾಚಾರವು ಭಾರತೀಯ ರಿಸರ್ವ್ ಬ್ಯಾಂಕ್ ಸೂಚಿಸಿದ ವಿಧಾನವನ್ನು ಅನುಸರಿಸುತ್ತದೆ. ಮೆಚುರಿಟಿ ಮೊತ್ತವನ್ನು ಖಾತರಿಪಡಿಸಲಾಗಿದೆ ಮತ್ತು ನಿಮ್ಮ ನೋಂದಾಯಿತ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಜಮಾ ಮಾಡಲಾಗುತ್ತದೆ.",
    "Interest rates based on active products. Rates vary by product type and tenure.": "ಸಕ್ರಿಯ ಉತ್ಪನ್ನಗಳ ಆಧಾರದ ಮೇಲೆ ಬಡ್ಡಿ ದರಗಳು. ಉತ್ಪನ್ನದ ಪ್ರಕಾರ ಮತ್ತು ಅವಧಿಗೆ ಅನುಗುಣವಾಗಿ ದರಗಳು ಬದಲಾಗುತ್ತವೆ.",
    "Interest rates vary by product type and tenure": "ಉತ್ಪನ್ನದ ಪ್ರಕಾರ ಮತ್ತು ಅವಧಿಯ ಆಧಾರದ ಮೇಲೆ ಬಡ್ಡಿದರಗಳು ಬದಲಾಗುತ್ತವೆ",
