    "Manage your default details for FD applications. These details will be auto-filled for future applications.": "FD ಅಪ್ಲಿಕೇಶನ್‌ಗಳಿಗಾಗಿ ನಿಮ್ಮ ಡೀಫಾಲ್ಟ್ ವಿವರಗಳನ್ನು ನಿರ್ವಹಿಸಿ. ಭವಿಷ್ಯದ ಅಪ್ಲಿಕೇಶನ್‌ಗಳಿಗಾಗಿ ಈ ವಿವರಗಳನ್ನು ಸ್ವಯಂ ತುಂಬಿಸಲಾಗುತ್ತದೆ.",
