    "Nomination facility is available for all FD accounts.": "ಎಲ್ಲಾ FD ಖಾತೆಗಳಿಗೆ ನಾಮನಿರ್ದೇಶನ ಸೌಲಭ್ಯ ಲಭ್ಯವಿದೆ.",
