    "Nominee details can be updated during the account tenure.": "ಖಾತೆಯ ಅವಧಿಯಲ್ಲಿ ನಾಮಿನಿ ವಿವರಗಳನ್ನು ನವೀಕರಿಸಬಹುದು.",
