    "Nominees (Optional)": "ನಾಮಿನಿಗಳು (ಐಚ್ಛಿಕ)",
    "Non-Resident Indians (NRIs) may apply subject to RBI regulations.": "ಅನಿವಾಸಿ ಭಾರತೀಯರು (NRI ಗಳು) RBI ನಿಯಮಗಳಿಗೆ ಒಳಪಟ್ಟು ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.",
    "Note: Calculations based on product-specific parameters and compound interest.": "ಗಮನಿಸಿ: ಉತ್ಪನ್ನ-ನಿರ್ದಿಷ್ಟ ನಿಯತಾಂಕಗಳು ಮತ್ತು ಸಂಯುಕ್ತ ಆಸಕ್ತಿಯ ಆಧಾರದ ಮೇಲೆ ಲೆಕ್ಕಾಚಾರಗಳು.",
    "Note: These charges are calculated based on current date and product terms.": "ಗಮನಿಸಿ: ಪ್ರಸ್ತುತ ದಿನಾಂಕ ಮತ್ತು ಉತ್ಪನ್ನದ ನಿಯಮಗಳ ಆಧಾರದ ಮೇಲೆ ಈ ಶುಲ್ಕಗಳನ್ನು ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ.",
    "Number of FDs": "FD ಗಳ ಸಂಖ್ಯೆ",
