    "Officer Sign in": "ಅಧಿಕಾರಿ ಸೈನ್ ಇನ್ ಮಾಡಿ",
    "On Maturity": "ಪ್ರಬುದ್ಧತೆಯ ಮೇಲೆ",
    "On maturity, the principal amount along with the accrued interest will be credited to your registered bank account. You will receive a notification before the maturity date.": "ಮುಕ್ತಾಯದ ನಂತರ, ಸಂಚಿತ ಬಡ್ಡಿಯೊಂದಿಗೆ ಅಸಲು ಮೊತ್ತವನ್ನು ನಿಮ್ಮ ನೋಂದಾಯಿತ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಜಮಾ ಮಾಡಲಾಗುತ್ತದೆ. ಮುಕ್ತಾಯ ದಿನಾಂಕದ ಮೊದಲು ನೀವು ಅಧಿಸೂಚನೆಯನ್ನು ಸ್ವೀಕರಿಸುತ್ತೀರಿ.",
    "On maturity, the principal and accrued interest will be credited to the linked bank account.": "ಮುಕ್ತಾಯದ ನಂತರ, ಅಸಲು ಮತ್ತು ಸಂಚಿತ ಬಡ್ಡಿಯನ್ನು ಲಿಂಕ್ ಮಾಡಲಾದ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಜಮಾ ಮಾಡಲಾಗುತ್ತದೆ.",
    "Open FD accounts and process transactions in real-time with zero delays.": "ಎಫ್‌ಡಿ ಖಾತೆಗಳನ್ನು ತೆರೆಯಿರಿ ಮತ್ತು ಶೂನ್ಯ ವಿಳಂಬದೊಂದಿಗೆ ನೈಜ ಸಮಯದಲ್ಲಿ ವಹಿವಾಟುಗಳನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಿ.",
    "Order": "ಆದೇಶ",
    "Other": "ಇತರೆ",
    "Our Mission": "ನಮ್ಮ ಮಿಷನ್",
    "Our Story": "ನಮ್ಮ ಕಥೆ",
    "Our Vision": "ನಮ್ಮ ದೃಷ್ಟಿ",
    "Our customers are at the heart of everything we do. We prioritize your financial well-being by offering transparent products, no hidden fees, and personalized support. Our dedicated relationship managers are available 24/7 to assist you with your investment decisions, ensuring you always make informed choices that align with your financial goals.": "ನಮ್ಮ ಗ್ರಾಹಕರು ನಾವು ಮಾಡುವ ಎಲ್ಲದರ ಹೃದಯಭಾಗದಲ್ಲಿರುತ್ತಾರೆ. ಪಾರದರ್ಶಕ ಉತ್ಪನ್ನಗಳು, ಯಾವುದೇ ಗುಪ್ತ ಶುಲ್ಕಗಳು ಮತ್ತು ವೈಯಕ್ತೀಕರಿಸಿದ ಬೆಂಬಲವನ್ನು ನೀಡುವ ಮೂಲಕ ನಿಮ್ಮ ಆರ್ಥಿಕ ಯೋಗಕ್ಷೇಮಕ್ಕೆ ನಾವು ಆದ್ಯತೆ ನೀಡುತ್ತೇವೆ. ನಿಮ್ಮ ಹೂಡಿಕೆಯ ನಿರ್ಧಾರಗಳೊಂದಿಗೆ ನಿಮಗೆ ಸಹಾಯ ಮಾಡಲು ನಮ್ಮ ಮೀಸಲಾದ ಸಂಬಂಧ ನಿರ್ವಾಹಕರು 24/7 ಲಭ್ಯವಿರುತ್ತಾರೆ, ನಿಮ್ಮ ಹಣಕಾಸಿನ ಗುರಿಗಳಿಗೆ ಹೊಂದಿಕೆಯಾಗುವ ತಿಳುವಳಿಕೆಯುಳ್ಳ ಆಯ್ಕೆಗಳನ್ನು ನೀವು ಯಾವಾಗಲೂ ಮಾಡುತ್ತೀರಿ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುತ್ತಾರೆ.",
    "Our platform may contain links to third-party websites or services. We are not responsible for the privacy practices or content of external sites. We encourage you to review the privacy policies of any third-party sites you visit. Our privacy policy applies only to information collected on our platform. Third-party links are provided for convenience and do not imply endorsement.": "ನಮ್ಮ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ವೆಬ್‌ಸೈಟ್‌ಗಳು ಅಥವಾ ಸೇವೆಗಳಿಗೆ ಲಿಂಕ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿರಬಹುದು. ಬಾಹ್ಯ ಸೈಟ್‌ಗಳ ಗೌಪ್ಯತೆ ಅಭ್ಯಾಸಗಳು ಅಥವಾ ವಿಷಯಕ್ಕೆ ನಾವು ಜವಾಬ್ದಾರರಾಗಿರುವುದಿಲ್ಲ. ನೀವು ಭೇಟಿ ನೀಡುವ ಯಾವುದೇ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಸೈಟ್‌ಗಳ ಗೌಪ್ಯತೆ ನೀತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ನಾವು ನಿಮ್ಮನ್ನು ಪ್ರೋತ್ಸಾಹಿಸುತ್ತೇವೆ. ನಮ್ಮ ಗೌಪ್ಯತಾ ನೀತಿಯು ನಮ್ಮ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನಲ್ಲಿ ಸಂಗ್ರಹಿಸಿದ ಮಾಹಿತಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ. ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಲಿಂಕ್‌ಗಳನ್ನು ಅನುಕೂಲಕ್ಕಾಗಿ ಒದಗಿಸಲಾಗಿದೆ ಮತ್ತು ಅನುಮೋದನೆಯನ್ನು ಸೂಚಿಸುವುದಿಲ್ಲ.",
    "Our services are not intended for individuals under the age of 18. We do not knowingly collect personal information from children. If we discover that we have collected information from a minor, we will take immediate steps to delete such information. Parents or guardians may contact us regarding data collection involving minors.": "ನಮ್ಮ ಸೇವೆಗಳು 18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನ ವ್ಯಕ್ತಿಗಳಿಗೆ ಉದ್ದೇಶಿಸಿಲ್ಲ. ನಾವು ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ಮಕ್ಕಳಿಂದ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ನಾವು ಅಪ್ರಾಪ್ತ ವಯಸ್ಕರಿಂದ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸಿದ್ದೇವೆ ಎಂದು ನಾವು ಕಂಡುಕೊಂಡರೆ, ಅಂತಹ ಮಾಹಿತಿಯನ್ನು ಅಳಿಸಲು ನಾವು ತಕ್ಷಣ ಕ್ರಮಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತೇವೆ. ಅಪ್ರಾಪ್ತ ವಯಸ್ಕರನ್ನು ಒಳಗೊಂಡ ಡೇಟಾ ಸಂಗ್ರಹಣೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಪೋಷಕರು ಅಥವಾ ಪೋಷಕರು ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು.",
    "Over the years, we have stayed true to our core values while embracing innovation. Today, we are proud to be at the forefront of digital banking, offering cutting-edge solutions without compromising on the personal touch that sets us apart.": "ವರ್ಷಗಳಲ್ಲಿ, ನಾವೀನ್ಯತೆಯನ್ನು ಅಳವಡಿಸಿಕೊಳ್ಳುವಾಗ ನಾವು ನಮ್ಮ ಪ್ರಮುಖ ಮೌಲ್ಯಗಳಿಗೆ ನಿಜವಾಗಿದ್ದೇವೆ. ಇಂದು, ಡಿಜಿಟಲ್ ಬ್ಯಾಂಕಿಂಗ್‌ನಲ್ಲಿ ಮುಂಚೂಣಿಯಲ್ಲಿರಲು ನಾವು ಹೆಮ್ಮೆಪಡುತ್ತೇವೆ, ನಮ್ಮನ್ನು ಪ್ರತ್ಯೇಕಿಸುವ ವೈಯಕ್ತಿಕ ಸ್ಪರ್ಶದಲ್ಲಿ ರಾಜಿ ಮಾಡಿಕೊಳ್ಳದೆ ಅತ್ಯಾಧುನಿಕ ಪರಿಹಾರಗಳನ್ನು ನೀಡುತ್ತೇವೆ.",
