    "Track your FD application status and approval timeline.": "ನಿಮ್ಮ FD ಅಪ್ಲಿಕೇಶನ್ ಸ್ಥಿತಿ ಮತ್ತು ಅನುಮೋದನೆಯ ಟೈಮ್‌ಲೈನ್ ಅನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.",
    "Transaction Report": "ವಹಿವಾಟು ವರದಿ",
    "Transaction report downloaded successfully!": "ವಹಿವಾಟು ವರದಿಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಡೌನ್‌ಲೋಡ್ ಮಾಡಲಾಗಿದೆ!",
    "Trusted by thousands of investors across India": "ಭಾರತದಾದ್ಯಂತ ಸಾವಿರಾರು ಹೂಡಿಕೆದಾರರಿಂದ ನಂಬಲಾಗಿದೆ",
    "Type:": "ಪ್ರಕಾರ:",
    "UNKNOWN": "ಅಜ್ಞಾತ",
    "UNO": "UNO",
    "UNO Bank Headquarters": "UNO ಬ್ಯಾಂಕ್ ಪ್ರಧಾನ ಕಛೇರಿ",
    "UNO Bank Headquarters, Banking Sector, Mumbai - 400001": "UNO ಬ್ಯಾಂಕ್ ಪ್ರಧಾನ ಕಛೇರಿ, ಬ್ಯಾಂಕಿಂಗ್ ವಲಯ, ಮುಂಬೈ - 400001",
    "UNO Bank Headquarters, Mumbai, Maharashtra, India": "UNO ಬ್ಯಾಂಕ್ ಪ್ರಧಾನ ಕಛೇರಿ, ಮುಂಬೈ, ಮಹಾರಾಷ್ಟ್ರ, ಭಾರತ",
    "UNO Bank Privacy Officer, Mumbai, Maharashtra, India": "UNO ಬ್ಯಾಂಕ್ ಗೌಪ್ಯತಾ ಅಧಿಕಾರಿ, ಮುಂಬೈ, ಮಹಾರಾಷ್ಟ್ರ, ಭಾರತ",
    "UNO Bank has transformed how I manage my investments. The competitive rates and seamless interface make it my go-to for fixed deposits.": "ನನ್ನ ಹೂಡಿಕೆಗಳನ್ನು ನಾನು ಹೇಗೆ ನಿರ್ವಹಿಸುತ್ತೇನೆ ಎಂಬುದನ್ನು UNO ಬ್ಯಾಂಕ್ ಪರಿವರ್ತಿಸಿದೆ. ಸ್ಪರ್ಧಾತ್ಮಕ ದರಗಳು ಮತ್ತು ತಡೆರಹಿತ ಇಂಟರ್ಫೇಸ್ ಸ್ಥಿರ ಠೇವಣಿಗಳಿಗೆ ನನ್ನ ಗೋ-ಟು ಮಾಡುತ್ತದೆ.",
    "UNO Bank operates under the strict regulatory framework of the Reserve Bank of India. We adhere to all banking regulations, maintain statutory liquidity ratios, and undergo regular audits to ensure the highest standards of financial integrity. Your deposits are insured up to ₹5 lakh under the DICGC scheme, providing you with complete peace of mind.": "UNO ಬ್ಯಾಂಕ್ ಭಾರತೀಯ ರಿಸರ್ವ್ ಬ್ಯಾಂಕ್‌ನ ಕಟ್ಟುನಿಟ್ಟಾದ ನಿಯಂತ್ರಣ ಚೌಕಟ್ಟಿನ ಅಡಿಯಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. ನಾವು ಎಲ್ಲಾ ಬ್ಯಾಂಕಿಂಗ್ ನಿಯಮಗಳಿಗೆ ಬದ್ಧರಾಗಿರುತ್ತೇವೆ, ಶಾಸನಬದ್ಧ ದ್ರವ್ಯತೆ ಅನುಪಾತಗಳನ್ನು ನಿರ್ವಹಿಸುತ್ತೇವೆ ಮತ್ತು ಹಣಕಾಸಿನ ಸಮಗ್ರತೆಯ ಉನ್ನತ ಗುಣಮಟ್ಟವನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ನಿಯಮಿತ ಲೆಕ್ಕಪರಿಶೋಧನೆಗೆ ಒಳಗಾಗುತ್ತೇವೆ. ನಿಮ್ಮ ಠೇವಣಿಗಳಿಗೆ ಡಿಐಸಿಜಿಸಿ ಯೋಜನೆಯಡಿ ₹5 ಲಕ್ಷದವರೆಗೆ ವಿಮೆ ಮಾಡಲಾಗಿದ್ದು, ನಿಮಗೆ ಸಂಪೂರ್ಣ ಮನಃಶಾಂತಿಯನ್ನು ಒದಗಿಸುತ್ತದೆ.",
    "UNO Bank shall not be liable for any indirect, incidental, or consequential damages. Our liability is limited to the amount of your deposit with us. We are not responsible for losses caused by force majeure events. Technical issues may temporarily affect service availability. We strive to maintain 99.9% uptime but cannot guarantee uninterrupted service.": "UNO ಬ್ಯಾಂಕ್ ಯಾವುದೇ ಪರೋಕ್ಷ, ಪ್ರಾಸಂಗಿಕ, ಅಥವಾ ಪರಿಣಾಮವಾಗಿ ಹಾನಿಗಳಿಗೆ ಜವಾಬ್ದಾರನಾಗಿರುವುದಿಲ್ಲ. ನಮ್ಮ ಹೊಣೆಗಾರಿಕೆಯು ನಮ್ಮಲ್ಲಿರುವ ನಿಮ್ಮ ಠೇವಣಿಯ ಮೊತ್ತಕ್ಕೆ ಸೀಮಿತವಾಗಿದೆ. ಬಲವಂತದ ಘಟನೆಗಳಿಂದ ಉಂಟಾಗುವ ನಷ್ಟಗಳಿಗೆ ನಾವು ಜವಾಬ್ದಾರರಲ್ಲ. ತಾಂತ್ರಿಕ ಸಮಸ್ಯೆಗಳು ಸೇವೆಯ ಲಭ್ಯತೆಯ ಮೇಲೆ ತಾತ್ಕಾಲಿಕವಾಗಿ ಪರಿಣಾಮ ಬೀರಬಹುದು. ನಾವು 99.9% ಅಪ್ಟೈಮ್ ಅನ್ನು ನಿರ್ವಹಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತೇವೆ ಆದರೆ ತಡೆರಹಿತ ಸೇವೆಯನ್ನು ಖಾತರಿಪಡಿಸುವುದಿಲ್ಲ.",
