    "✅ SIGNUP RESPONSE RECEIVED:": "✅ ಸೈನ್ ಅಪ್ ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ಸ್ವೀಕರಿಸಲಾಗಿದೆ:",
