    "❌ VALIDATION FAILED: Passwords do not match": "❌ ಮೌಲ್ಯೀಕರಣ ವಿಫಲವಾಗಿದೆ: ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ",
