    "🌙 Dark": "🌙 ಕತ್ತಲೆ",
    "🎁 Special rates available": "🎁 ವಿಶೇಷ ದರಗಳು ಲಭ್ಯವಿದೆ",
    "📝 INPUTS RECEIVED:": "📝 ಇನ್‌ಪುಟ್‌ಗಳನ್ನು ಸ್ವೀಕರಿಸಲಾಗಿದೆ:",
